// Package the uploaded CSV rows + form config into one state item.
const form = $('Upload Meta Ads CSV').first().json || {};
const rows = $input.all().map(function (i) { return i.json; });
const config = {
  monthly_budget: Number(form.monthly_budget),
  target_cpa: Number(form.target_cpa),
  analysis_date: form.analysis_date,
  currency: form.currency || 'HKD',
};
return [{ json: { source: 'upload', config: config, raw_rows: rows } }];

const state = $input.first().json || {};
const config = state.config || {};
const rawRows = state.raw_rows || [];
const currency = config.currency || 'HKD';

const errors = [];
const warnings = [];

// Canonical target columns and their recognised aliases (already key-normalized).
const ALIASES = {
  date: ['date', 'day', 'reporting starts', 'reporting start', 'reporting ends'],
  campaign_name: ['campaign name', 'campaign'],
  spend: ['amount spent', 'spend', 'cost'],
  impressions: ['impressions', 'impr'],
  clicks: ['link clicks', 'clicks', 'clicks all'],
  conversions: ['results', 'purchases', 'conversions', 'website purchases'],
  revenue: ['purchase conversion value', 'purchases conversion value', 'conversion value', 'revenue'],
  ad_name: ['ad name', 'ad'],
};

function normKey(k) {
  return String(k).toLowerCase().replace(/\([^)]*\)/g, ' ').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}
function canonicalFor(k) {
  const nk = normKey(k);
  for (const canon in ALIASES) {
    if (ALIASES[canon].indexOf(nk) !== -1) return canon;
  }
  return null;
}
function cleanNum(v) {
  if (v === null || v === undefined) return null;
  let s = String(v).replace(/[^0-9.\-]/g, '').trim();
  if (s === '' || s === '-' || s === '.') return null;
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
}
function parseDate(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (s === '') return null;
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); // YYYY-MM-DD
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); // MM/DD/YYYY
  if (m) {
    const mm = (m[1].length < 2 ? '0' : '') + m[1];
    const dd = (m[2].length < 2 ? '0' : '') + m[2];
    return m[3] + '-' + mm + '-' + dd;
  }
  const d = new Date(s);
  if (!isNaN(d.getTime())) {
    const y = d.getUTCFullYear();
    const mm = ('0' + (d.getUTCMonth() + 1)).slice(-2);
    const dd = ('0' + d.getUTCDate()).slice(-2);
    return y + '-' + mm + '-' + dd;
  }
  return null;
}

// Discover which canonical columns exist across the header set.
const present = {};
for (const row of rawRows) {
  for (const key in row) {
    const canon = canonicalFor(key);
    if (canon) present[canon] = true;
  }
}
const REQUIRED = ['date', 'campaign_name', 'spend', 'impressions', 'clicks', 'conversions'];
const missing = REQUIRED.filter(function (c) { return !present[c]; });
if (missing.length) {
  errors.push('Missing required column(s): ' + missing.join(', ') + '. Please include these headers (aliases are accepted).');
}
if (!present.revenue) warnings.push('No revenue/Purchase Conversion Value column found — ROAS will be omitted.');
if (!present.ad_name) warnings.push('No Ad Name column found — creative deterioration will be evaluated at campaign level.');

const normalized = [];
let rowNum = 0;
for (const row of rawRows) {
  rowNum++;
  // Map raw row into canonical fields.
  const mapped = {};
  let allEmpty = true;
  for (const key in row) {
    const canon = canonicalFor(key);
    if (!canon) continue;
    const val = row[key];
    if (val !== null && val !== undefined && String(val).trim() !== '') allEmpty = false;
    mapped[canon] = val;
  }
  if (allEmpty) continue; // remove empty rows

  const campaignRaw = mapped.campaign_name ? String(mapped.campaign_name).trim() : '';
  // Drop summary / total rows.
  if (campaignRaw === '' || /^(total|totals|grand total|summary)$/i.test(campaignRaw)) continue;

  const dateVal = parseDate(mapped.date);
  if (missing.length === 0 && !dateVal) {
    errors.push('Row ' + rowNum + ': date value "' + String(mapped.date) + '" could not be parsed.');
  }

  const rec = {
    date: dateVal,
    campaign_name: campaignRaw,
    spend: cleanNum(mapped.spend),
    impressions: cleanNum(mapped.impressions),
    clicks: cleanNum(mapped.clicks),
    conversions: cleanNum(mapped.conversions),
  };
  if (present.revenue) rec.revenue = cleanNum(mapped.revenue);
  if (present.ad_name && mapped.ad_name !== undefined) rec.ad_name = String(mapped.ad_name).trim();

  // Validate required numerics (never invent missing values).
  if (missing.length === 0) {
    ['spend', 'impressions', 'clicks', 'conversions'].forEach(function (f) {
      if (rec[f] === null) {
        errors.push('Row ' + rowNum + ' (' + campaignRaw + '): could not parse numeric value for "' + f + '".');
      }
    });
  }
  normalized.push(rec);
}

if (normalized.length === 0 && errors.length === 0) {
  errors.push('No usable data rows were found after cleaning.');
}

const validDates = normalized.map(function (r) { return r.date; }).filter(Boolean).sort();
const campaigns = {};
normalized.forEach(function (r) { campaigns[r.campaign_name] = true; });

const input_summary = {
  row_count: normalized.length,
  date_start: validDates.length ? validDates[0] : '',
  date_end: validDates.length ? validDates[validDates.length - 1] : '',
  campaign_count: Object.keys(campaigns).length,
  currency: currency,
};

const validation_status = errors.length === 0 ? 'valid' : 'invalid';

return [{ json: {
  validation_status: validation_status,
  errors: errors,
  warnings: warnings,
  normalized_rows: normalized,
  input_summary: input_summary,
  config: config,
} }];

// Deterministic demo dataset using Meta Ads export headers (same schema as an upload).
// 5 campaigns exercise every rule: overspend (account), CPA deterioration,
// creative deterioration, controlled scaling, and insufficient data.
const analysisDate = '2026-08-18'; // analysis month = August 2026
const config = { monthly_budget: 100000, target_cpa: 250, analysis_date: analysisDate, currency: 'HKD' };

function iso(y, m, d) {
  const mm = (m < 10 ? '0' : '') + m;
  const dd = (d < 10 ? '0' : '') + d;
  return y + '-' + mm + '-' + dd;
}

// 30 calendar days of data: 2026-07-20 .. 2026-08-18
const dates = [];
for (let d = 20; d <= 31; d++) dates.push({ y: 2026, m: 7, d: d });
for (let d = 1; d <= 18; d++) dates.push({ y: 2026, m: 8, d: d });

const rows = [];
function push(dt, campaign, ad, spend, impr, clicks, results, revenue) {
  const r = {};
  r['Day'] = iso(dt.y, dt.m, dt.d);
  r['Campaign Name'] = campaign;
  r['Ad Name'] = ad;
  r['Amount Spent (HKD)'] = spend;
  r['Impressions'] = impr;
  r['Link Clicks'] = clicks;
  r['Results'] = results;
  r['Purchase Conversion Value'] = revenue;
  rows.push(r);
}

for (const dt of dates) {
  const isAug = dt.m === 8;
  const recentWeek = isAug && dt.d >= 12; // Aug 12-18

  // 1) Aurora Skincare -> drives account overspending (very high spend).
  push(dt, 'Aurora Skincare', 'Aurora - Prospecting', isAug ? 2800 : 1500, 20000, 200, 8, 8 * 300);

  // 2) Nimbus Footwear -> CPA deterioration (recent CPA >= prev CPA * 1.2).
  const nSpend = recentWeek ? 240 : 200;
  const nRes = recentWeek ? 3 : 4;
  push(dt, 'Nimbus Footwear', 'Nimbus - BAU', nSpend, 3000, 30, nRes, nRes * 180);

  // 3) Solaris Home -> creative deterioration (CTR down >=15%, CPC up >=20%).
  const sSpend = recentWeek ? 105 : 100;
  const sClicks = recentWeek ? 10 : 12;
  push(dt, 'Solaris Home', 'Solaris - Video A', sSpend, 1000, sClicks, 1, 1 * 150);

  // 4) Verdant Coffee -> controlled scaling opportunity.
  const vSpend = recentWeek ? 600 : 571.43;
  push(dt, 'Verdant Coffee', 'Verdant - Retargeting', vSpend, 5000, 60, 3, 3 * 400);

  // 5) Pixel Games -> insufficient data (only 3 days, tiny volume).
  if (isAug && dt.d >= 16) {
    push(dt, 'Pixel Games', 'Pixel - Launch', 10, 100, 2, 1, 0);
  }
}

return [{ json: { source: 'demo', config: config, raw_rows: rows } }];

const state = $input.first().json || {};
const rows = state.normalized_rows || [];
const config = state.config || {};
const currency = (state.input_summary && state.input_summary.currency) || config.currency || 'HKD';
const budget = Number(config.monthly_budget) || 0;

// Division-by-zero safe helper: returns null when denominator is 0/invalid.
function sd(a, b) { return (b && b !== 0) ? a / b : null; }
function toUTC(ds) { const p = String(ds).split('-'); return Date.UTC(+p[0], +p[1] - 1, +p[2]); }

const analysisDate = config.analysis_date;
const ap = String(analysisDate).split('-');
const aY = +ap[0], aM = +ap[1], aDay = +ap[2];
const aMs = toUTC(analysisDate);
const dayMs = 86400000;
const recentStart = aMs - 6 * dayMs; // recent 7 days: analysis_date-6 .. analysis_date
const prevEnd = aMs - 7 * dayMs;      // previous 7 days: analysis_date-13 .. analysis_date-7
const prevStart = aMs - 13 * dayMs;
const totalDaysInMonth = new Date(Date.UTC(aY, aM, 0)).getUTCDate();

function emptyAgg() { return { spend: 0, impressions: 0, clicks: 0, conversions: 0, revenue: 0, has_revenue: false, days: 0 }; }
function addRow(a, r) {
  a.spend += (+r.spend || 0);
  a.impressions += (+r.impressions || 0);
  a.clicks += (+r.clicks || 0);
  a.conversions += (+r.conversions || 0);
  if (r.revenue !== undefined && r.revenue !== null && r.revenue !== '') { a.revenue += (+r.revenue || 0); a.has_revenue = true; }
  a.days += 1;
}
function derive(a) {
  return {
    spend: a.spend, impressions: a.impressions, clicks: a.clicks, conversions: a.conversions,
    revenue: a.has_revenue ? a.revenue : null,
    ctr: sd(a.clicks, a.impressions),   // clicks / impressions
    cpc: sd(a.spend, a.clicks),          // spend / clicks
    cvr: sd(a.conversions, a.clicks),    // conversions / clicks
    cpa: sd(a.spend, a.conversions),     // spend / conversions
    roas: a.has_revenue ? sd(a.revenue, a.spend) : null, // revenue / spend (only when revenue exists)
  };
}

const acct = emptyAgg();
const acctRecent = emptyAgg();
const acctPrev = emptyAgg();
const campMap = {};
let mtdSpend = 0;
const mtdDates = {};
let minMonthDay = 99;

for (const r of rows) {
  if (!r.date) continue;
  const ms = toUTC(r.date);
  addRow(acct, r);
  const inRecent = ms >= recentStart && ms <= aMs;
  const inPrev = ms >= prevStart && ms <= prevEnd;
  if (inRecent) addRow(acctRecent, r);
  if (inPrev) addRow(acctPrev, r);

  const pp = String(r.date).split('-');
  const ry = +pp[0], rm = +pp[1], rd = +pp[2];
  if (ry === aY && rm === aM && rd <= aDay) { mtdSpend += (+r.spend || 0); mtdDates[r.date] = true; if (rd < minMonthDay) minMonthDay = rd; }

  const cname = r.campaign_name;
  if (!campMap[cname]) campMap[cname] = { name: cname, tot: emptyAgg(), rec: emptyAgg(), prev: emptyAgg(), groups: {}, hasAd: false };
  const c = campMap[cname];
  addRow(c.tot, r);
  if (inRecent) addRow(c.rec, r);
  if (inPrev) addRow(c.prev, r);

  const hasAd = r.ad_name !== undefined && r.ad_name !== null && String(r.ad_name).trim() !== '';
  if (hasAd) c.hasAd = true;
  const gkey = hasAd ? String(r.ad_name).trim() : cname;
  if (!c.groups[gkey]) c.groups[gkey] = { key: gkey, rec: emptyAgg(), prev: emptyAgg() };
  if (inRecent) addRow(c.groups[gkey].rec, r);
  if (inPrev) addRow(c.groups[gkey].prev, r);
}

// ---- Month-end spend forecast (transparent linear pacing) ----
const distinctMonthDates = Object.keys(mtdDates).length;
const elapsedDays = aDay; // elapsed calendar days = day-of-month of analysis_date
const enough7 = distinctMonthDates >= 7;
const startsNearMonthStart = minMonthDay <= 3;
const missingRatio = elapsedDays > 0 ? (1 - distinctMonthDates / elapsedDays) : 1;
const notTooMissing = missingRatio <= 0.20;
let forecast_status, projected, forecast_note;
if (enough7 && startsNearMonthStart && notTooMissing) {
  forecast_status = 'ok';
  // Projected Month-End Spend = MTD Spend / Elapsed Calendar Days * Total Calendar Days in Month
  const perDay = sd(mtdSpend, elapsedDays);
  projected = perDay === null ? null : perDay * totalDaysInMonth;
  forecast_note = 'Linear pacing estimate (MTD spend / elapsed days x days in month). NOT a machine-learning prediction.';
} else {
  forecast_status = 'insufficient';
  projected = null;
  forecast_note = 'Insufficient Data for Reliable Forecast';
}

const overall = derive(acct);
overall.mtd_spend = mtdSpend;
overall.elapsed_days = elapsedDays;
overall.total_days_in_month = totalDaysInMonth;
overall.distinct_month_dates = distinctMonthDates;
overall.projected_month_end_spend = projected;
overall.budget = budget;
overall.budget_ratio = (budget > 0 && projected != null) ? projected / budget : null;
overall.forecast_status = forecast_status;
overall.forecast_note = forecast_note;
overall.forecast_method = 'Projected Month-End Spend = Month-to-Date Spend / Elapsed Calendar Days x Total Calendar Days in Month (linear pacing estimate, not ML).';
overall.recent7 = derive(acctRecent);
overall.previous7 = derive(acctPrev);

const campaign_metrics = Object.keys(campMap).map(function (k) {
  const c = campMap[k];
  const groups = Object.keys(c.groups).map(function (gk) {
    const g = c.groups[gk];
    const gr = derive(g.rec);
    const gp = derive(g.prev);
    return {
      group_key: g.key,
      level: c.hasAd ? 'ad' : 'campaign',
      recent: { impressions: gr.impressions, clicks: gr.clicks, spend: gr.spend, ctr: gr.ctr, cpc: gr.cpc },
      previous: { impressions: gp.impressions, clicks: gp.clicks, spend: gp.spend, ctr: gp.ctr, cpc: gp.cpc },
    };
  });
  return {
    campaign_name: c.name,
    has_ad_names: c.hasAd,
    totals: derive(c.tot),
    recent7: derive(c.rec),
    previous7: derive(c.prev),
    groups: groups,
  };
});

state.currency = currency;
state.overall_metrics = overall;
state.campaign_metrics = campaign_metrics;
state.insights = [];
return [{ json: state }];

const s = $input.first().json;
const om = s.overall_metrics || {};
const budget = Number(s.config.monthly_budget) || 0;
const proj = om.projected_month_end_spend;
const ratio = om.budget_ratio;

// Thresholds: >110% overspend, <90% underspend, else on track.
let status, priority, title, what, why, action, confidence, sufficiency;
why = 'Budget pacing determines whether the account will over- or under-spend the monthly budget if current daily spend continues.';
if (om.forecast_status === 'insufficient' || proj == null || budget <= 0) {
  status = 'insufficient_data'; priority = 'none'; title = 'Budget Pacing: Insufficient Data';
  what = 'A reliable month-end spend forecast could not be produced, so budget pacing cannot be assessed.';
  action = 'Ensure the export covers the full month-to-date starting near the 1st with no large date gaps.';
  confidence = 'low'; sufficiency = 'Forecast requirements not met.';
} else if (ratio > 1.10) {
  status = 'triggered'; priority = 'high'; title = 'Overspending Risk';
  what = 'Projected month-end spend is ' + (ratio * 100).toFixed(1) + '% of the monthly budget (above the 110% threshold).';
  action = 'Review daily budgets/bids on the highest-spend campaigns to bring pacing back toward budget.';
  confidence = 'high'; sufficiency = 'Forecast produced from sufficient month-to-date data.';
} else if (ratio < 0.90) {
  status = 'triggered'; priority = 'medium'; title = 'Underspending Risk';
  what = 'Projected month-end spend is ' + (ratio * 100).toFixed(1) + '% of the monthly budget (below the 90% threshold).';
  action = 'Consider reallocating budget to efficient campaigns to fully use the planned budget.';
  confidence = 'high'; sufficiency = 'Forecast produced from sufficient month-to-date data.';
} else {
  status = 'on_track'; priority = 'low'; title = 'Budget On Track';
  what = 'Projected month-end spend is ' + (ratio * 100).toFixed(1) + '% of the monthly budget (within the 90-110% band).';
  action = 'No budget action required; continue monitoring.';
  confidence = 'high'; sufficiency = 'Forecast produced from sufficient month-to-date data.';
}

s.insights.push({
  rule_id: 'rule_1_budget_pacing',
  title: title,
  status: status,
  priority: priority,
  what_happened: what,
  evidence: {
    monthly_budget: budget,
    month_to_date_spend: om.mtd_spend,
    elapsed_calendar_days: om.elapsed_days,
    total_days_in_month: om.total_days_in_month,
    projected_month_end_spend: proj,
    budget_ratio: ratio,
    overspend_threshold: 1.10,
    underspend_threshold: 0.90,
  },
  why_it_matters: why,
  recommended_action: action,
  confidence: confidence,
  data_sufficiency: sufficiency,
});
return [{ json: s }];

const s = $input.first().json;
const camps = s.campaign_metrics || [];
const MIN_CONV = 15;      // each 7-day window needs >=15 conversions
const TRIGGER = 1.20;     // recent CPA >= previous CPA * 1.20

const triggered = [];
const details = [];
let anyEvaluated = false;
camps.forEach(function (c) {
  const rc = c.recent7.conversions;
  const pc = c.previous7.conversions;
  const rCpa = c.recent7.cpa;
  const pCpa = c.previous7.cpa;
  const evaluable = rc >= MIN_CONV && pc >= MIN_CONV && rCpa != null && pCpa != null;
  const row = { campaign: c.campaign_name, recent_conversions: rc, previous_conversions: pc, recent_cpa: rCpa, previous_cpa: pCpa, ratio: (pCpa ? rCpa / pCpa : null), evaluable: evaluable };
  if (evaluable) {
    anyEvaluated = true;
    if (rCpa >= pCpa * TRIGGER) { row.result = 'deteriorated'; triggered.push(row); }
    else row.result = 'stable';
  } else {
    row.result = 'insufficient_data';
  }
  details.push(row);
});

let status, priority, title, what, action, confidence, sufficiency;
if (triggered.length) {
  status = 'triggered'; priority = 'high'; title = 'CPA Deterioration Detected';
  const names = triggered.map(function (t) { return t.campaign; }).join(', ');
  what = 'CPA rose at least 20% week-over-week for: ' + names + '.';
  action = 'Investigate audience saturation, bid changes and landing-page/offer factors for the affected campaigns.';
  confidence = 'high'; sufficiency = 'Both 7-day windows met the 15-conversion minimum for the flagged campaigns.';
} else if (anyEvaluated) {
  status = 'stable'; priority = 'low'; title = 'CPA Stable';
  what = 'No campaign with sufficient volume showed a 20%+ week-over-week CPA increase.';
  action = 'No action required; continue monitoring CPA trends.';
  confidence = 'high'; sufficiency = 'At least one campaign met the 15-conversion minimum in both windows.';
} else {
  status = 'insufficient_data'; priority = 'none'; title = 'CPA Deterioration: Insufficient Data';
  what = 'No campaign had at least 15 conversions in both the recent and previous 7-day windows.';
  action = 'Collect more conversion volume before assessing CPA trend reliability.';
  confidence = 'low'; sufficiency = 'Conversion volume below the 15-per-window minimum.';
}

s.insights.push({
  rule_id: 'rule_2_cpa_deterioration',
  title: title, status: status, priority: priority, what_happened: what,
  evidence: { min_conversions_per_window: MIN_CONV, trigger_multiplier: TRIGGER, campaigns: details },
  why_it_matters: 'A sharp CPA increase signals eroding efficiency and rising cost to acquire each customer.',
  recommended_action: action, confidence: confidence, data_sufficiency: sufficiency,
});
return [{ json: s }];

const s = $input.first().json;
const camps = s.campaign_metrics || [];
const MIN_IMPR = 5000;   // per 7-day window
const MIN_CLICKS = 50;   // per 7-day window
const CTR_DROP = 0.15;   // CTR down >= 15%
const CPC_RISE = 0.20;   // CPC up >= 20%

const triggered = [];
const details = [];
let anyEvaluated = false;
camps.forEach(function (c) {
  c.groups.forEach(function (g) {
    const r = g.recent, p = g.previous;
    const evaluable = r.impressions >= MIN_IMPR && r.clicks >= MIN_CLICKS && p.impressions >= MIN_IMPR && p.clicks >= MIN_CLICKS && r.ctr != null && p.ctr != null && r.cpc != null && p.cpc != null;
    const row = { campaign: c.campaign_name, group: g.group_key, level: g.level, recent_ctr: r.ctr, previous_ctr: p.ctr, recent_cpc: r.cpc, previous_cpc: p.cpc, recent_impressions: r.impressions, recent_clicks: r.clicks, evaluable: evaluable };
    if (evaluable) {
      anyEvaluated = true;
      const ctrDown = r.ctr <= p.ctr * (1 - CTR_DROP);
      const cpcUp = r.cpc >= p.cpc * (1 + CPC_RISE);
      row.ctr_change = (r.ctr - p.ctr) / p.ctr;
      row.cpc_change = (r.cpc - p.cpc) / p.cpc;
      if (ctrDown && cpcUp) { row.result = 'deteriorated'; triggered.push(row); }
      else row.result = 'stable';
    } else {
      row.result = 'insufficient_data';
    }
    details.push(row);
  });
});

let status, priority, title, what, action, confidence, sufficiency;
if (triggered.length) {
  status = 'triggered'; priority = 'high'; title = 'Creative Performance Deterioration';
  const names = triggered.map(function (t) { return t.group; }).join(', ');
  what = 'CTR fell at least 15% AND CPC rose at least 20% week-over-week for: ' + names + '.';
  action = 'Refresh or rotate the affected creatives and review frequency; verify the cause before assuming fatigue.';
  confidence = 'medium'; sufficiency = 'Both windows met the 5,000 impressions / 50 clicks minimums for the flagged items.';
} else if (anyEvaluated) {
  status = 'stable'; priority = 'low'; title = 'Creative Performance Stable';
  what = 'No creative/campaign with sufficient volume showed the combined CTR drop and CPC rise pattern.';
  action = 'No action required; continue monitoring creative efficiency.';
  confidence = 'medium'; sufficiency = 'At least one item met the impression/click minimums in both windows.';
} else {
  status = 'insufficient_data'; priority = 'none'; title = 'Creative Deterioration: Insufficient Data';
  what = 'No creative/campaign met the 5,000 impressions and 50 clicks minimums in both 7-day windows.';
  action = 'Allow more delivery before assessing creative deterioration.';
  confidence = 'low'; sufficiency = 'Impression/click volume below minimums.';
}

s.insights.push({
  rule_id: 'rule_3_creative_deterioration',
  title: title, status: status, priority: priority, what_happened: what,
  evidence: { min_impressions_per_window: MIN_IMPR, min_clicks_per_window: MIN_CLICKS, ctr_drop_threshold: CTR_DROP, cpc_rise_threshold: CPC_RISE, items: details },
  why_it_matters: 'A simultaneous CTR decline and CPC increase indicates weakening creative resonance and rising delivery cost. This is a performance signal, not a confirmed cause of creative fatigue.',
  recommended_action: action, confidence: confidence, data_sufficiency: sufficiency,
});
return [{ json: s }];

const s = $input.first().json;
const camps = s.campaign_metrics || [];
const om = s.overall_metrics || {};
const target = Number(s.config.target_cpa) || 0;
const MIN_CONV = 15;              // recent 7-day conversions
const BELOW_TARGET = 0.85;        // recent CPA <= 85% of target (>=15% below)
const MAX_WOW_DETER = 0.10;       // week-over-week CPA deterioration <= 10%
const BUDGET_GATE = 1.20;         // account forecast must NOT be clearly above 110% (treated as <=120%)

// Account-level guardrail: scaling is withheld if the account is clearly pacing over budget.
const ratio = om.budget_ratio;
