  h.push('<article class="' + cls + '"><div class="alert-head"><div><span class="eyebrow">' + esc(i.rule_id) + '</span><h3>' + esc(i.title) + '</h3></div><span class="pill">' + esc(i.priority) + ' priority</span></div>');
  h.push('<div class="section-label">What happened</div><p>' + esc(i.what_happened) + '</p>');
  h.push('<div class="section-label">Key evidence</div>' + evidenceHtml(i));
  h.push('<div class="section-label">Why it matters</div><p>' + esc(i.why_it_matters) + '</p>');
  h.push('<div class="section-label">Rule-level recommendation</div><p>' + esc(i.recommended_action) + '</p>');
  h.push('<p class="muted"><strong>Confidence:</strong> ' + esc(i.confidence || 'not stated') + ' · <strong>Data sufficiency:</strong> ' + esc(i.data_sufficiency || 'not stated') + '</p></article>');
});
h.push('</section>');

h.push('<section><h2>Recommended Action Plan</h2><div class="action-stack">');
insights.filter(function (i) { return i.status !== 'insufficient_data'; }).sort(function (a, b) { return priorityRank(a.priority) - priorityRank(b.priority); }).forEach(function (i) { h.push(planCard(i)); });
h.push('</div></section>');

if (insuff.length) {
  h.push('<section><h2>Insufficient-Data Notices</h2>');
  insuff.forEach(function (i) {
    h.push('<div class="notice"><strong>' + esc(i.title) + '</strong><br>' + esc(i.what_happened) + '<br><span class="muted">' + esc(i.data_sufficiency || '') + '</span></div>');
  });
  h.push('</section>');
}

h.push('<section><h2>Methodology &amp; Limitations</h2><div class="method">');
h.push('<p><strong>Forecast:</strong> ' + esc(methodology.forecast_method) + '</p>');
h.push('<p><strong>Comparison windows:</strong> ' + esc(methodology.comparison_windows) + '</p><h4>Rule thresholds</h4><ul>');
Object.keys(methodology.rule_thresholds).forEach(function (k) { h.push('<li><strong>' + esc(k) + ':</strong> ' + esc(methodology.rule_thresholds[k]) + '</li>'); });
h.push('</ul><h4>Limitations</h4><ul>');
methodology.limitations.forEach(function (l) { h.push('<li>' + esc(l) + '</li>'); });
h.push('</ul></div></section>');

h.push('<p class="foot">AccountPulse MVP — explainable, deterministic paid-media review. No campaigns were modified. Optional AI narrative remains disabled.</p>');
h.push('</main></body></html>');

report.html_report = h.join('');
return [{ json: report }];

